759	async function captureBody(request,index) {
760	  const label='body_'+String(index).padStart(4,'0');
761	  mkdir(label);
762	  const d=inputByPath.get(request.lexical_path), resolution=resolveBound(d.path);
763	  same(resolution.resolved,d.resolved,'approved body resolution');
764	  record(label+'/ATTEMPT.json',{schema:'p212-body-copy-attempt-v1',request,
765	    exact_bound_descriptor:d,alias_chain:resolution.chain,
766	    source_read_operation:'open O_RDONLY|O_NOFOLLOW|O_NONBLOCK on fully bound regular referent; read in ordered chunks',
767	    destination_operation:'exclusive new body.raw; complete bytes or retained partial failure',
768	    authorization_receipt:binding.receipts.body_scope});
769	  const sourceFd=fs.openSync(d.resolved,
770	    fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW|fs.constants.O_NONBLOCK);
771	  let destFd=null;
772	  try {
773	    const before=fs.fstatSync(sourceFd,{bigint:true});
774	    need(before.isFile(),'body referent must be regular file, never device/socket/directory');
775	    assertMetadata(stats(before),d.stat,'stable','body handle before');
776	    destFd=openOutput(label+'/body.raw');
777	    const hash=crypto.createHash('sha256'),buffer=Buffer.alloc(1024*1024);
778	    let total=0;
779	    while(true) {
780	      const n=fs.readSync(sourceFd,buffer,0,buffer.length,null); if(n===0) break;
781	      total+=n;
782	      // Retain the actually read chunk, then reject oversized output; never
783	      // relabel a truncated prefix as a whole body.
784	      let at=0; while(at<n) at+=fs.writeSync(destFd,buffer,at,n-at);
785	      hash.update(buffer.subarray(0,n));
786	      need(total<=request.max_bytes,'body exceeded bound; partial failure retained');
787	    }
788	    fs.fsyncSync(destFd);
789	    const after=fs.fstatSync(sourceFd,{bigint:true});
790	    assertMetadata(stats(after),stats(before),'stable','same body read handle after');
791	    same(BigInt(total),before.size,'complete same-handle body size');
792	    const bodyPin={bytes:total,sha256:hash.digest('hex')};
793	    if(d.content!==null) same(bodyPin,d.content,'prebound body bytes');
794	    if(bodyObservations.has(d.path))
795	      same(bodyPin,bodyObservations.get(d.path),'duplicate returned body unchanged');
796	    bodyObservations.set(d.path,bodyPin);
797	    record(label+'/READ_HANDLE.json',{lexical:d.path,resolved:d.resolved,
798	      before:stats(before),after:stats(after),body:bodyPin,
799	      operation:'actual ordered fs.readSync/fs.writeSync exclusive full copy',
800	      native_external_read_copy_envelope:'REQUIRED_SEPARATE_ROOT_CAPTURE',

801	      continuous_path_race_claim:false});
802	    fs.closeSync(destFd); destFd=null;
803	    const comparison=await nativeCapture(label+'_cmp',
804	      ['/usr/bin/cmp','--',d.path,out+'/'+label+'/body.raw'],[0]);
805	    need(comparison.result.allowed_native_exit&&comparison.result.native_exit.code===0,
806	      'actual byte comparison failed');
807	    need(comparison.stdout.length===0&&comparison.stderr.length===0,'cmp diagnostics require reception');
808	    const finalResolution=resolveBound(d.path);
809	    same(finalResolution.resolved,d.resolved,'body alias chain after');
810	    const finalStat=fs.statSync(d.path,{bigint:true});
811	    assertMetadata(stats(finalStat),stats(before),'stable','body path after actual cmp');
812	    same(pin(fs.readFileSync(out+'/'+label+'/body.raw')),bodyPin,'retained copy after native cmp');
813	    record(label+'/RESULT.json',{request,lexical:d.path,resolved:d.resolved,
814	      read_handle_before:stats(before),read_handle_after:stats(after),
815	      path_stat_after_cmp:stats(finalStat),alias_chain_before:resolution.chain,
816	      alias_chain_after:finalResolution.chain,body:bodyPin,
817	      raw_cmp_result:label+'_cmp/RESULT.json',
818	      source_semantics_received:false,source_edges:null,dependency_lock:null,
819	      root_original_reception:'PENDING'});
820	    return {request,body_file:label+'/body.raw',pin:bodyPin};
821	  } finally {
822	    fs.closeSync(sourceFd); if(destFd!==null) fs.closeSync(destFd);
823	  }
824	}
825	function sealLocal() {
